mapper.select:
SELECT  FROM crm_batch_tag_preview_member
WHERE tenant_id=#{tenantId} AND preview_id=#{previewId} ORDER BY customer_id
LIMIT #{size} OFFSET #{offset}

mapper.sql:
FROM crm_batch_tag_job WHERE tenant_id=#{tenantId}
AND (#{scopeType}='ALL' OR requested_by=#{requestedBy})
AND status=#{status}

mapper.update:
UPDATE crm_batch_tag_job SET lease_expires_at=#{leaseExpiresAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status='RUNNING' AND lease_owner=#{leaseOwner}

mapper.select:
SELECT  FROM crm_batch_tag_job
WHERE tenant_id=#{tenantId} AND status='RUNNING' AND lease_expires_at IS NOT NULL
  AND lease_expires_at<=#{now} ORDER BY id LIMIT #{limit}

mapper.sql:
FROM crm_customer_segment_batch_member bm
INNER JOIN crm_customer c ON c.tenant_id=bm.tenant_id AND c.id=bm.customer_id
WHERE bm.tenant_id=#{tenantId} AND bm.batch_id=#{batchId} AND c.deleted=0



    AND (c.owner_staff_id=#{selfId}

      OR c.team_id IN #{teamId}
    )

  AND c.owner_staff_id=#{selfId}
  AND 1=0

mapper.select:
SELECT c.id,c.tenant_id,c.customer_no,c.display_name,c.nickname,c.owner_staff_id,c.team_id
 ORDER BY c.id
LIMIT #{size} OFFSET #{offset}
